#!/usr/bin/env bash
# Add the Bible lock's DeviceActivity monitor extension to the generated
# Xcode project.
#
# The lock has to come back at the start of each day whether or not anyone
# opens Bible Buddy, and only a DeviceActivityMonitor extension gets woken for
# that. An extension is a second target, and ios/ is regenerated by
# `npx cap add ios` on every build - so like the Info.plist keys, the icon and
# the entitlements, it has to be added after generation rather than committed.
#
# Uses the xcodeproj gem, which is already on Codemagic's macs as part of
# CocoaPods. Run from the repo root, after `cap sync` and before `xcodebuild`.
set -euo pipefail

PROJECT="ios/App/App.xcodeproj"
SOURCE_DIR="native/ios-extensions/BibleLockMonitor"
TARGET_NAME="BibleLockMonitor"
DEST="ios/App/$TARGET_NAME"

if [ ! -d "$PROJECT" ]; then
  echo "No Xcode project at $PROJECT - run 'npx cap add ios' first." >&2
  exit 1
fi

mkdir -p "$DEST"
cp "$SOURCE_DIR"/*.swift "$DEST/"
cp "$SOURCE_DIR/Info.plist" "$DEST/"
cp "$SOURCE_DIR/BibleLockMonitor.entitlements" "$DEST/"

# The app target needs the same App Group, or it writes the chosen apps
# somewhere the extension cannot read.
APP_ENTITLEMENTS="ios/App/App/App.entitlements"
if [ -f "$APP_ENTITLEMENTS" ] && ! grep -q "application-groups" "$APP_ENTITLEMENTS"; then
  /usr/libexec/PlistBuddy -c "Add :com.apple.security.application-groups array" "$APP_ENTITLEMENTS"
  /usr/libexec/PlistBuddy -c "Add :com.apple.security.application-groups:0 string group.net.mybiblebuddy.app" "$APP_ENTITLEMENTS"
  echo "Added the App Group to the app target's entitlements."
fi

ruby <<'RUBY'
require 'xcodeproj'

project_path = 'ios/App/App.xcodeproj'
target_name  = 'BibleLockMonitor'
project = Xcodeproj::Project.open(project_path)

if project.targets.any? { |t| t.name == target_name }
  puts "#{target_name} is already in the project; leaving it alone."
  exit 0
end

app = project.targets.find { |t| t.name == 'App' } or abort 'No App target found.'

ext = project.new_target(
  :app_extension,
  target_name,
  :ios,
  '16.0',
  nil,
  :swift
)

# The group already carries the folder name, so a reference of
# "BibleLockMonitor/BibleLockMonitor.swift" inside it resolves to
# BibleLockMonitor/BibleLockMonitor/BibleLockMonitor.swift and the archive
# says the input files cannot be found. Just the filename.
group = project.main_group.new_group(target_name, target_name)
%w[BibleLockMonitor.swift BibleLockShared.swift].each do |file|
  ref = group.new_reference(file)
  ext.add_file_references([ref])
end
group.new_reference('Info.plist')
group.new_reference('BibleLockMonitor.entitlements')

ext.build_configurations.each do |config|
  s = config.build_settings
  # Without this the product is built as ".appex" with nothing in front of
  # it, and the embed phase then has two commands producing the same path:
  #   error: Multiple commands produce .../UninstalledProducts/iphoneos/.appex
  # xcodeproj does not set it, and Xcode usually would.
  s['PRODUCT_NAME'] = target_name
  # The Info.plist refers to these. They are placeholders: this step runs
  # before the version step, and agvtool -all then writes the real numbers
  # across every target. Without the keys existing, the substitution resolves
  # to empty and Apple rejects the upload for a missing version.
  s['MARKETING_VERSION'] = '1.0'
  s['CURRENT_PROJECT_VERSION'] = '1'
  s['PRODUCT_BUNDLE_IDENTIFIER'] = 'net.mybiblebuddy.app.biblelockmonitor'
  s['INFOPLIST_FILE'] = "#{target_name}/Info.plist"
  s['CODE_SIGN_ENTITLEMENTS'] = "#{target_name}/BibleLockMonitor.entitlements"
  s['IPHONEOS_DEPLOYMENT_TARGET'] = '16.0'
  s['SWIFT_VERSION'] = '5.0'
  s['TARGETED_DEVICE_FAMILY'] = '1,2'
  s['GENERATE_INFOPLIST_FILE'] = 'NO'
  s['SKIP_INSTALL'] = 'YES'
  # Inherit the team from the app rather than hard-coding it, so this keeps
  # working if the account ever moves.
  s['DEVELOPMENT_TEAM'] = app.build_configurations.first.build_settings['DEVELOPMENT_TEAM']
end

# Embed it in the app, and make sure the app waits for it to build.
app.add_dependency(ext)
embed = app.new_copy_files_build_phase('Embed App Extensions')
embed.symbol_dst_subfolder_spec = :plug_ins
embed.add_file_reference(ext.product_reference)

project.save
puts "Added #{target_name} to the Xcode project."
RUBY

echo "--- extension entitlements ---"
cat "$DEST/BibleLockMonitor.entitlements"
